using System.Reflection;
using Aspire.Hosting;
using Aspire.Hosting.ApplicationModel;
using CommunityToolkit.Aspire.Hosting.Dapr;
using Intropy.Topology.Generation;
using Intropy.Topology.Model;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;

namespace Intropy.Topology.Aspire;

/// <summary>
/// The Aspire run-backend. Discovers a system's validated topology, generates its Dapr
/// components, and translates the model into Aspire resources — one project per component
/// with a Dapr sidecar on its own staged component overlay, and RabbitMQ behind pub/sub —
/// then runs it under DCP, subscribers before their publishers. Scheduled components are
/// re-run on their cron ticks by the <see cref="ComponentScheduler"/> (CronJob emulation,
/// with a "Run now" dashboard command). Aspire never sees the topology; it receives
/// ordinary resources.
/// </summary>
public static class IntropyAspire
{
    /// <summary>Fixed host port for the local RabbitMQ backend (generated pub/sub YAML points here).</summary>
    internal const int RabbitMqPort = 5672;

    /// <summary>
    /// Discovers the system in <paramref name="assembly"/>, generates its artifacts to a temp folder,
    /// builds the Aspire resource graph, and runs it. Requires Docker and the Dapr CLI to be present.
    /// </summary>
    /// <param name="assembly">The assembly declaring the <see cref="ISystemDefinition"/>.</param>
    /// <param name="args">Command-line args passed through to the distributed application builder.</param>
    /// <returns>A process exit code.</returns>
    public static async Task<int> RunAsync(Assembly assembly, string[] args)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        ArgumentNullException.ThrowIfNull(args);

        var discovered = SystemDiscovery.Discover(assembly);

        var generatedRoot = Path.Combine(
            Path.GetTempPath(), "intropy-aspire", $"{discovered.Topology.SystemName}-{Guid.NewGuid():N}");
        TopologyGenerator.Generate(discovered.Topology).WriteTo(generatedRoot);

        var builder = DistributedApplication.CreateBuilder(args);
        Apply(builder, discovered.Topology, generatedRoot);

        var app = builder.Build();
        await app.RunAsync().ConfigureAwait(false);
        return 0;
    }

    /// <summary>
    /// Translates the topology into Aspire resources on <paramref name="builder"/>. Separated from
    /// <see cref="RunAsync"/> so the built model can be inspected in tests without running DCP.
    /// </summary>
    internal static void Apply(
        IDistributedApplicationBuilder builder, SystemTopology topology, string generatedRoot)
    {
        var componentsPath = Path.Combine(generatedRoot, GeneratedArtifacts.ComponentsDir);
        var configDir = Path.Combine(generatedRoot, GeneratedArtifacts.ConfigDir);

        // A plain RabbitMQ container rather than AddRabbitMQ: the generated pub/sub YAML speaks
        // default guest/guest to localhost:5672, while AddRabbitMQ injects generated credentials.
        var rabbitmq = builder
            .AddContainer("rabbitmq", "docker.io/library/rabbitmq", "4")
            .WithEndpoint(port: RabbitMqPort, targetPort: RabbitMqPort);
        WithTcpReadiness(builder, rabbitmq, RabbitMqPort);

        // Everything a sidecar dials during component init. Sidecars must wait for these to be
        // *ready* (not merely running) — daprd treats a failed component init as fatal, so racing
        // a still-starting backend kills the sidecar.
        var backends = new List<IResourceBuilder<IResource>> { rabbitmq };
        var backendProbes = new List<TcpReadyHealthCheck> { new("localhost", RabbitMqPort) };

        // Filled after the component loop; the hook closure only reads it at runtime.
        var sidecarWaits = new Dictionary<string, string[]>(StringComparer.Ordinal);

        // The Dapr toolkit materializes each sidecar as a separate "<component>-dapr-cli" executable
        // that does not carry wait annotations, so WaitFor cannot gate it. Hold its start here until
        // every backend port answers and, for publishers, until every subscriber sidecar is running.
        builder.Eventing.Subscribe<BeforeResourceStartedEvent>(async (evt, cancellationToken) =>
        {
            if (!evt.Resource.Name.EndsWith("-dapr-cli", StringComparison.Ordinal))
            {
                return;
            }

            foreach (var probe in backendProbes)
            {
                await probe.WaitUntilReadyAsync(TimeSpan.FromMinutes(3), cancellationToken).ConfigureAwait(false);
            }

            if (sidecarWaits.TryGetValue(evt.Resource.Name, out var subscriberSidecars))
            {
                var notifications = evt.Services.GetRequiredService<ResourceNotificationService>();
                foreach (var sidecar in subscriberSidecars)
                {
                    await notifications
                        .WaitForResourceAsync(sidecar, KnownResourceStates.Running, cancellationToken)
                        .ConfigureAwait(false);
                }
            }
        });

        var resources = new Dictionary<string, IResourceBuilder<IResource>>(StringComparer.Ordinal);
        var waiters = new Dictionary<string, Action<IResourceBuilder<IResource>>>(StringComparer.Ordinal);
        var unresolved = new List<string>();
        foreach (var component in topology.Components)
        {
            // Each integration gets its own staged component set: its local files plus the
            // generated system overlay, at a stable inspectable path under obj/.
            var stagedPath = ComponentOverlay.Stage(builder.AppHostDirectory, component.Name, componentsPath);

            var projectPath = ProjectConvention.Resolve(builder.AppHostDirectory, component.Name);
            if (!File.Exists(projectPath))
            {
                unresolved.Add($"{component.Name} (expected {projectPath})");
                continue;
            }

            var project = builder.AddProject(component.Name, projectPath);
            if (component.Schedule is null)
            {
                // The endpoint makes Aspire allocate a port and inject ASPNETCORE_URLS (without it
                // every Kestrel binds the 5000 default) and gives the Dapr sidecar its app-port.
                // A scheduled component is a run-to-completion job that receives no inbound
                // delivery, so it gets neither.
                project = project.WithHttpEndpoint();
            }
            else
            {
                AddRunNowCommand(project, component.Name);
            }

            Wire(project, component, stagedPath, configDir, backends);
            resources[component.Name] = project;
            waiters[component.Name] = dependency => project.WaitFor(dependency);
        }

        RegisterDaprSidecarRecovery(builder, backendProbes);
        RegisterScheduler(builder, topology);

        if (unresolved.Count > 0)
        {
            throw new InvalidOperationException(
                $"No project found for these components by folder convention: {string.Join(", ", unresolved)}. " +
                "Create the project next to the SystemHost.");
        }

        // Subscribers start first, so a publisher's first message finds a registered
        // subscription. Nobody declares this: it is derived from who publishes and who
        // subscribes each topic. Publish/subscribe cycles cannot be ordered — skip entirely
        // rather than deadlock.
        var precedence = SubscriberPrecedence(topology);
        if (HasCycle(precedence))
        {
            Console.Error.WriteLine(
                "intropy: the topology's topics form a publish/subscribe cycle; " +
                "skipping subscriber-first startup ordering.");
            return;
        }

        foreach (var (publisher, subscribers) in precedence)
        {
            if (!waiters.TryGetValue(publisher, out var wait))
            {
                continue;
            }

            var materialized = subscribers.Where(resources.ContainsKey).ToArray();
            foreach (var subscriber in materialized)
            {
                wait(resources[subscriber]);
            }

            if (materialized.Length > 0)
            {
                sidecarWaits[$"{publisher}-dapr-cli"] =
                    [.. materialized.Select(s => $"{s}-dapr-cli")];
            }
        }
    }

    /// <summary>
    /// Registers the <see cref="ComponentScheduler"/> when any component declares a schedule.
    /// Keyed off <c>Schedule</c>, not the component kind — the scheduler is kind-blind.
    /// </summary>
    private static void RegisterScheduler(IDistributedApplicationBuilder builder, SystemTopology topology)
    {
        var scheduled = topology.Components
            .Where(c => c.Schedule is not null)
            .Select(c => new ScheduledComponent(c.Name, c.Schedule!))
            .ToArray();
        if (scheduled.Length == 0)
        {
            return;
        }

        builder.Services.TryAddSingleton(TimeProvider.System);
        builder.Services.AddSingleton<IReadOnlyList<ScheduledComponent>>(scheduled);
        builder.Services.TryAddSingleton<IResourceLifecycle, AspireResourceLifecycle>();
        builder.Services.AddSingleton<ComponentScheduler>();
        builder.Services.AddHostedService(sp => sp.GetRequiredService<ComponentScheduler>());
    }

    /// <summary>
    /// Registers recovery for every Dapr sidecar, including unscheduled components. The normal
    /// pre-start gate prevents the common race; recovery covers the remaining interval where a
    /// backend passes TCP readiness but daprd's component initialization still fails.
    /// </summary>
    private static void RegisterDaprSidecarRecovery(
        IDistributedApplicationBuilder builder, IReadOnlyList<TcpReadyHealthCheck> backendProbes)
    {
        builder.Services.TryAddSingleton<IResourceLifecycle, AspireResourceLifecycle>();
        builder.Services.AddSingleton<IResourceStateMonitor, AspireResourceStateMonitor>();
        builder.Services.AddSingleton<IBackendReadiness>(
            new BackendReadiness(backendProbes.Cast<IBackendReadiness>().ToArray()));
        builder.Services.AddSingleton<DaprSidecarRecovery>();
        builder.Services.AddHostedService(sp => sp.GetRequiredService<DaprSidecarRecovery>());
    }

    /// <summary>
    /// A dashboard command that triggers a scheduled component immediately, through the same
    /// path as a cron tick — including the skip when the previous run is still in progress.
    /// </summary>
    private static void AddRunNowCommand(IResourceBuilder<ProjectResource> project, string componentName)
    {
        project.WithCommand(
            name: "intropy-run-now",
            displayName: "Run now",
            executeCommand: async context =>
            {
                var scheduler = context.ServiceProvider.GetRequiredService<ComponentScheduler>();
                await scheduler.TriggerAsync(componentName, "manual run", context.CancellationToken)
                    .ConfigureAwait(false);
                return CommandResults.Success();
            },
            commandOptions: new CommandOptions { IconName = "Play", IconVariant = IconVariant.Filled });
    }

    /// <summary>
    /// Which components each publisher must wait for: every subscriber of every topic it
    /// publishes. Self-loops (a component consuming its own topic) are not orderable edges.
    /// </summary>
    private static Dictionary<string, HashSet<string>> SubscriberPrecedence(SystemTopology topology)
    {
        var precedence = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
        foreach (var topic in topology.Topics)
        {
            foreach (var publisher in topic.Publishers)
            {
                foreach (var subscriber in topic.Subscribers)
                {
                    if (string.Equals(publisher, subscriber, StringComparison.Ordinal))
                    {
                        continue;
                    }

                    if (!precedence.TryGetValue(publisher, out var subscribers))
                    {
                        precedence[publisher] = subscribers = new HashSet<string>(StringComparer.Ordinal);
                    }

                    subscribers.Add(subscriber);
                }
            }
        }

        return precedence;
    }

    private static bool HasCycle(Dictionary<string, HashSet<string>> edges)
    {
        var state = new Dictionary<string, int>(StringComparer.Ordinal); // 1 = visiting, 2 = done

        bool Visit(string node)
        {
            if (state.TryGetValue(node, out var seen))
            {
                return seen == 1;
            }

            state[node] = 1;
            if (edges.TryGetValue(node, out var next) && next.Any(Visit))
            {
                return true;
            }

            state[node] = 2;
            return false;
        }

        return edges.Keys.Any(Visit);
    }

    private static void WithTcpReadiness(
        IDistributedApplicationBuilder builder, IResourceBuilder<ContainerResource> container, int port)
    {
        var key = $"{container.Resource.Name}-tcp-ready";
        builder.Services.AddHealthChecks().AddCheck(key, new TcpReadyHealthCheck("localhost", port));
        container.WithHealthCheck(key);
    }

    private static void Wire<T>(
        IResourceBuilder<T> resource,
        ComponentModel component,
        string resourcesPath,
        string configDir,
        IReadOnlyList<IResourceBuilder<IResource>> backends)
        where T : IResourceWithEnvironment, IResourceWithWaitSupport
    {
        resource
            .WithDaprSidecar(sidecar =>
            {
                sidecar.WithOptions(new DaprSidecarOptions
                {
                    AppId = component.Name,
                    ResourcesPaths = [resourcesPath],
                });
                foreach (var backend in backends)
                {
                    sidecar.WaitFor(backend);
                }
            })
            .WithEnvironment("INTROPY__COMPONENT", component.Name)
            .WithEnvironment("INTROPY__CONFIG", Path.Combine(configDir, $"{component.Name}.intropy.json"));

        foreach (var backend in backends)
        {
            resource.WaitFor(backend);
        }
    }
}

namespace Intropy.Topology.Model;

/// <summary>
/// The immutable, validated topology of one integration system: its components (in
/// declaration order) and the resources materialized from their usage (sorted).
/// Plain serializable data — generation tooling consumes this model.
/// </summary>
public sealed record SystemTopology
{
    /// <summary>The system's name (DNS-1123 label).</summary>
    public required string SystemName { get; init; }

    /// <summary>All components, in declaration order.</summary>
    public required IReadOnlyList<ComponentModel> Components { get; init; }

    /// <summary>Topics materialized from publish and subscribe edges.</summary>
    public required IReadOnlyList<TopicResource> Topics { get; init; }

    /// <summary>Connectors materialized from connector usage.</summary>
    public required IReadOnlyList<ConnectorResource> Connectors { get; init; }
}

using Intropy.Topology.Building;
using Intropy.Topology.Model;
using Intropy.Topology.Validation;

namespace Intropy.Topology;

/// <summary>
/// Entry point for declaring an integration system's topology. Add components, wire
/// them to topics and connectors, then call <see cref="Build"/> to materialize and
/// validate the immutable <see cref="SystemTopology"/>. Resources (topics, connectors)
/// materialize from usage — there is no <c>AddTopic</c>. Not thread-safe;
/// a second <see cref="Build"/> after further mutation reflects the mutations.
/// </summary>
public sealed class SystemBuilder
{
    private readonly List<Component> _components = [];

    /// <summary>The system's name (DNS-1123 label).</summary>
    public string SystemName { get; }

    private SystemBuilder(string systemName)
    {
        SystemName = systemName;
    }

    internal IReadOnlyList<Component> Components => _components;

    /// <summary>Creates a builder for a named system.</summary>
    /// <param name="systemName">The system's name (DNS-1123 label).</param>
    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
    public static SystemBuilder Create(string systemName) =>
        new(NameRules.RequireLabel(systemName, nameof(systemName)));

    /// <summary>Adds an extractor: pulls data out of an external system and publishes it.</summary>
    /// <param name="name">The component's name (DNS-1123 label).</param>
    public ExtractorBuilder AddExtractor(string name) =>
        new(Register(new ExtractorComponent(NameRules.RequireLabel(name, nameof(name)))));

    /// <summary>Adds a loader: consumes a topic and writes to an external system.</summary>
    /// <param name="name">The component's name (DNS-1123 label).</param>
    public LoaderBuilder AddLoader(string name) =>
        new(Register(new LoaderComponent(NameRules.RequireLabel(name, nameof(name)))));

    /// <summary>Adds a transactional integration.</summary>
    /// <param name="name">The component's name (DNS-1123 label).</param>
    public TransactionalIntegrationBuilder AddTransactionalIntegration(string name) =>
        new(Register(new TransactionalIntegrationComponent(NameRules.RequireLabel(name, nameof(name)))));

    /// <summary>
    /// Materializes and validates the topology. Throws when any error-severity
    /// violation exists, carrying every diagnostic found.
    /// </summary>
    /// <exception cref="TopologyValidationException">The declared topology is invalid.</exception>
    public SystemTopology Build() =>
        TryBuild(out var topology, out var diagnostics)
            ? topology!
            : throw new TopologyValidationException(diagnostics);

    /// <summary>Non-throwing <see cref="Build"/>: returns false with the diagnostics when the topology is invalid.</summary>
    /// <param name="topology">The topology when valid; null otherwise.</param>
    /// <param name="diagnostics">All diagnostics found, including warnings.</param>
    public bool TryBuild(out SystemTopology? topology, out IReadOnlyList<TopologyDiagnostic> diagnostics)
    {
        var candidate = TopologyMaterializer.Materialize(this);
        diagnostics = TopologyRules.Run(this, candidate);
        if (diagnostics.Any(d => d.Severity == DiagnosticSeverity.Error))
        {
            topology = null;
            return false;
        }

        topology = candidate;
        return true;
    }

    /// <summary>Runs validation without throwing; returns all diagnostics including warnings.</summary>
    public IReadOnlyList<TopologyDiagnostic> Validate() =>
        TopologyRules.Run(this, TopologyMaterializer.Materialize(this));

    private T Register<T>(T component) where T : Component
    {
        _components.Add(component);
        return component;
    }
}

using Aspire.Hosting;
using Aspire.Hosting.ApplicationModel;
using CommunityToolkit.Aspire.Hosting.Dapr;
using Intropy.Topology;
using Intropy.Topology.Generation;
using Intropy.Topology.Model;

namespace Intropy.Topology.Aspire.Test;

public sealed class IntropyAspireTests : IDisposable
{
    private sealed record RawOrder(string OrderNumber);

    private static readonly TopicRef<RawOrder> s_raw = TopicRef<RawOrder>.Define("pubsub-a", "order-raw");
    private static readonly ConnectorRef s_webshop = ConnectorRef.Define("webshop", Transport.File("./test/webshop"));
    private static readonly ConnectorRef s_erp = ConnectorRef.Define("erp", Transport.File("./test/erp"));

    private const string GeneratedRoot = "/tmp/intropy-aspire-test";

    // Apply resolves each component to a project on disk by folder convention, so every
    // test gets a workspace with the AppHost and one flat-layout project per component.
    private readonly string _workspace = Directory.CreateTempSubdirectory("intropy-aspire-").FullName;

    private string AppHostDir => Path.Combine(_workspace, "system-host");

    public IntropyAspireTests()
    {
        Directory.CreateDirectory(AppHostDir);
        WriteProject("order-extractor");
        WriteProject("order-loader");
    }

    public void Dispose() => Directory.Delete(_workspace, recursive: true);

    private void WriteProject(string componentName)
    {
        var dir = Directory.CreateDirectory(Path.Combine(_workspace, componentName)).FullName;
        File.WriteAllText(Path.Combine(dir, componentName + ".csproj"), "<Project />");
    }

    private IDistributedApplicationBuilder CreateBuilder() =>
        DistributedApplication.CreateBuilder(new DistributedApplicationOptions { ProjectDirectory = AppHostDir });

    private static SystemTopology Topology()
    {
        var s = SystemBuilder.Create("order-flow");
        s.AddExtractor("order-extractor").From(s_webshop).Publishes(s_raw);
        s.AddLoader("order-loader").Subscribes(s_raw).To(s_erp);
        return s.Build();
    }

    [Fact]
    public void Apply_ShouldAddRabbitMqBackend()
    {
        // Arrange
        var builder = CreateBuilder();

        // Act
        IntropyAspire.Apply(builder, Topology(), GeneratedRoot);

        // Assert
        Assert.Contains(builder.Resources, r => r.Name == "rabbitmq");
    }

    [Fact]
    public void Apply_ShouldAddProjectPerComponent_WithSidecarAppId()
    {
        // Arrange
        var builder = CreateBuilder();

        // Act
        IntropyAspire.Apply(builder, Topology(), GeneratedRoot);

        // Assert
        Assert.Equal("order-extractor", SidecarOptions(builder, "order-extractor").AppId);
        Assert.Equal("order-loader", SidecarOptions(builder, "order-loader").AppId);
    }

    [Fact]
    public void REDACTED()
    {
        // Arrange
        var builder = CreateBuilder();

        // Act
        IntropyAspire.Apply(builder, Topology(), GeneratedRoot);

        // Assert — each sidecar loads its own staged set, not a shared directory.
        var expected = Path.Combine(builder.AppHostDirectory, "obj", "dapr-components", "order-extractor");
        Assert.Contains(expected, SidecarOptions(builder, "order-extractor").ResourcesPaths!);
        Assert.DoesNotContain(expected, SidecarOptions(builder, "order-loader").ResourcesPaths!);
    }

    [Fact]
    public void Apply_ShouldMakePublisherWaitForItsSubscribers()
    {
        // Arrange — order-extractor publishes order-raw; order-loader subscribes it.
        var builder = CreateBuilder();

        // Act
        IntropyAspire.Apply(builder, Topology(), GeneratedRoot);

        // Assert — derived from the topology: the publisher waits, the subscriber does not.
        var extractor = builder.Resources.Single(r => r.Name == "order-extractor");
        Assert.Contains(
            extractor.Annotations.OfType<WaitAnnotation>(),
            w => w.Resource.Name == "order-loader");
        var loader = builder.Resources.Single(r => r.Name == "order-loader");
        Assert.DoesNotContain(
            loader.Annotations.OfType<WaitAnnotation>(),
            w => w.Resource.Name == "order-extractor");
    }

    [Fact]
    public async Task Apply_ShouldInjectRuntimeConfigEnvironment()
    {
        // Arrange
        var builder = CreateBuilder();
        IntropyAspire.Apply(builder, Topology(), GeneratedRoot);
        var resource = builder.Resources.OfType<IResourceWithEnvironment>().Single(r => r.Name == "order-extractor");

        // Act — publish-mode evaluation: the intropy variables are plain strings, and run-mode
        // evaluation of a project resource would wait for endpoint allocation that never happens
        // outside DCP.
        var env = await resource.GetEnvironmentVariableValuesAsync(DistributedApplicationOperation.Publish);

        // Assert
        Assert.Equal("order-extractor", env["INTROPY__COMPONENT"]);
        Assert.Equal(
            Path.Combine(GeneratedRoot, GeneratedArtifacts.ConfigDir, "order-extractor.intropy.json"),
            env["INTROPY__CONFIG"]);
    }

    [Fact]
    public void REDACTED()
    {
        // Arrange — order-loader has no project on disk.
        Directory.Delete(Path.Combine(_workspace, "order-loader"), recursive: true);
        var builder = CreateBuilder();

        // Act / Assert
        var ex = Assert.Throws<InvalidOperationException>(
            () => IntropyAspire.Apply(builder, Topology(), GeneratedRoot));
        Assert.Contains("order-loader", ex.Message, StringComparison.Ordinal);
        Assert.Contains("No project found", ex.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void ProjectConvention_Resolve_ShouldFallBackToFlatSiblingLayout()
    {
        // Act — no src/ directory exists, so the flat layout applies.
        var path = ProjectConvention.Resolve("/repo/examples/OrderFlow.SystemHost", "order-extractor");

        // Assert
        Assert.Equal(
            Path.GetFullPath("/repo/examples/order-extractor/order-extractor.csproj"),
            path);
    }

    [Fact]
    public void ProjectConvention_Resolve_ShouldPreferSingleProjectUnderSrc()
    {
        // Arrange — the scaffold layout: <name>/src/<Project>.csproj
        var src = Directory.CreateDirectory(Path.Combine(_workspace, "order-transformer", "src")).FullName;
        var project = Path.Combine(src, "OrderTransformer.csproj");
        File.WriteAllText(project, "<Project />");

        // Act
        var path = ProjectConvention.Resolve(AppHostDir, "order-transformer");

        // Assert
        Assert.Equal(project, path);
    }

    [Fact]
    public void ProjectConvention_LocalComponentsDir_ShouldPointIntoTheIntegrationRoot()
    {
        // Act
        var dir = ProjectConvention.LocalComponentsDir("/repo/examples/OrderFlow.SystemHost", "order-extractor");

        // Assert
        Assert.Equal(
            Path.GetFullPath("/repo/examples/order-extractor/local/dapr-components"),
            dir);
    }

    private static DaprSidecarOptions SidecarOptions(IDistributedApplicationBuilder builder, string componentName)
    {
        var resource = builder.Resources.Single(r => r.Name == componentName);
        var sidecar = Assert.Single(resource.Annotations.OfType<DaprSidecarAnnotation>()).Sidecar;
        return Assert.Single(((IResource)sidecar).Annotations.OfType<DaprSidecarOptionsAnnotation>()).Options;
    }
}
